DROP TABLE IF EXISTS "failed_jobs";
CREATE TABLE "failed_jobs" ( "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, "connection" text NOT NULL, "queue" text NOT NULL, "payload" TEXT NOT NULL, "exception" TEXT NOT NULL, "failed_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_commission_log";
CREATE TABLE "v2_commission_log" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "invite_user_id" INTEGER NOT NULL, "user_id" INTEGER NOT NULL, "trade_no" char(36) NOT NULL, "order_amount" INTEGER NOT NULL, "get_amount" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_coupon";
CREATE TABLE "v2_coupon" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "code" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "type" SMALLINT NOT NULL, "value" INTEGER NOT NULL, "show" SMALLINT NOT NULL DEFAULT '0', "limit_use" INTEGER DEFAULT NULL, "limit_use_with_user" INTEGER DEFAULT NULL, "limit_plan_ids" varchar(255) DEFAULT NULL, "limit_period" varchar(255) DEFAULT NULL, "started_at" INTEGER NOT NULL, "ended_at" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_giftcard";
CREATE TABLE "v2_giftcard" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "code" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "type" SMALLINT NOT NULL, "value" INTEGER DEFAULT NULL, "plan_id" INTEGER DEFAULT NULL, "limit_use" INTEGER DEFAULT NULL, "used_user_ids" varchar(16384) DEFAULT NULL, "started_at" INTEGER NOT NULL, "ended_at" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_invite_code";
CREATE TABLE "v2_invite_code" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "user_id" INTEGER NOT NULL, "code" varchar(32) NOT NULL, "status" SMALLINT NOT NULL DEFAULT '0', "invite_campaign_id" INTEGER DEFAULT NULL, "pv" INTEGER NOT NULL DEFAULT '0', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_knowledge";
CREATE TABLE "v2_knowledge" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "language" char(5) NOT NULL, "category" varchar(255) NOT NULL, "title" varchar(255) NOT NULL, "body" text NOT NULL, "sort" INTEGER DEFAULT NULL, "show" SMALLINT NOT NULL DEFAULT '0', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_log";
CREATE TABLE "v2_log" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "title" text NOT NULL, "level" varchar(11) DEFAULT NULL, "host" varchar(255) DEFAULT NULL, "uri" varchar(255) NOT NULL, "method" varchar(11) NOT NULL, "data" text, "ip" varchar(128) DEFAULT NULL, "context" text, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_mail_log";
CREATE TABLE "v2_mail_log" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "email" varchar(64) NOT NULL, "subject" varchar(255) NOT NULL, "template_name" varchar(255) NOT NULL, "error" text, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_notice";
CREATE TABLE "v2_notice" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "title" varchar(255) NOT NULL, "content" text NOT NULL, "show" SMALLINT NOT NULL DEFAULT '0', "img_url" varchar(255) DEFAULT NULL, "tags" varchar(255) DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_order";
CREATE TABLE "v2_order" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "invite_user_id" INTEGER DEFAULT NULL, "user_id" INTEGER NOT NULL, "plan_id" INTEGER NOT NULL, "coupon_id" INTEGER DEFAULT NULL, "payment_id" INTEGER DEFAULT NULL, "type" INTEGER NOT NULL, "period" varchar(255) NOT NULL, "trade_no" varchar(36) NOT NULL, "callback_no" varchar(255) DEFAULT NULL, "total_amount" INTEGER NOT NULL, "handling_amount" INTEGER DEFAULT NULL, "discount_amount" INTEGER DEFAULT NULL, "surplus_amount" INTEGER DEFAULT NULL, "refund_amount" INTEGER DEFAULT NULL, "balance_amount" INTEGER DEFAULT NULL, "surplus_order_ids" text, "status" SMALLINT NOT NULL DEFAULT '0', "commission_status" SMALLINT NOT NULL DEFAULT '0', "commission_balance" INTEGER NOT NULL DEFAULT '0', "actual_commission_balance" INTEGER DEFAULT NULL, "invite_campaign_id" INTEGER DEFAULT NULL, "invite_campaign_discount_amount" INTEGER NOT NULL DEFAULT '0', "paid_at" INTEGER DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "trade_no" UNIQUE ("trade_no") );
CREATE INDEX "idx_v2_order_user_id" ON "v2_order" ("user_id");
CREATE INDEX "idx_v2_order_user_id_status" ON "v2_order" ("user_id", "status");
DROP TABLE IF EXISTS "v2_invite_campaign";
CREATE TABLE "v2_invite_campaign" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "user_id" INTEGER NOT NULL, "plan_id" INTEGER NOT NULL, "period" varchar(32) NOT NULL, "invite_code_id" INTEGER DEFAULT NULL, "invite_code" varchar(32) DEFAULT NULL, "reward_amount" INTEGER NOT NULL, "target_amount" INTEGER NOT NULL, "current_amount" INTEGER NOT NULL DEFAULT '0', "invite_count" INTEGER NOT NULL DEFAULT '0', "status" SMALLINT NOT NULL DEFAULT '0', "started_at" INTEGER NOT NULL, "expired_at" INTEGER NOT NULL, "completed_at" INTEGER DEFAULT NULL, "abandoned_at" INTEGER DEFAULT NULL, "used_at" INTEGER DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
CREATE INDEX "idx_v2_invite_campaign_user_id_status" ON "v2_invite_campaign" ("user_id", "status");
DROP TABLE IF EXISTS "v2_invite_campaign_record";
CREATE TABLE "v2_invite_campaign_record" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "campaign_id" INTEGER NOT NULL, "invitee_user_id" INTEGER NOT NULL, "invite_code" varchar(32) NOT NULL, "reward_amount" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "uniq_campaign_invitee" UNIQUE ("campaign_id", "invitee_user_id") );
CREATE INDEX "idx_v2_invite_campaign_record_campaign_id" ON "v2_invite_campaign_record" ("campaign_id");
DROP TABLE IF EXISTS "v2_payment";
CREATE TABLE "v2_payment" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "uuid" char(32) NOT NULL, "payment" varchar(16) NOT NULL, "name" varchar(255) NOT NULL, "icon" varchar(255) DEFAULT NULL, "config" text NOT NULL, "notify_domain" varchar(128) DEFAULT NULL, "handling_fee_fixed" INTEGER DEFAULT NULL, "handling_fee_percent" decimal(5,2) DEFAULT NULL, "enable" SMALLINT NOT NULL DEFAULT '0', "sort" INTEGER DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_plan";
CREATE TABLE "v2_plan" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "group_id" INTEGER NOT NULL, "transfer_enable" INTEGER NOT NULL, "device_limit" INTEGER DEFAULT NULL, "name" varchar(255) NOT NULL, "speed_limit" INTEGER DEFAULT NULL, "show" SMALLINT NOT NULL DEFAULT '0', "sort" INTEGER DEFAULT NULL, "renew" SMALLINT NOT NULL DEFAULT '1', "content" text, "month_price" INTEGER DEFAULT NULL, "quarter_price" INTEGER DEFAULT NULL, "half_year_price" INTEGER DEFAULT NULL, "year_price" INTEGER DEFAULT NULL, "two_year_price" INTEGER DEFAULT NULL, "three_year_price" INTEGER DEFAULT NULL, "onetime_price" INTEGER DEFAULT NULL, "reset_price" INTEGER DEFAULT NULL, "reset_traffic_method" SMALLINT DEFAULT NULL, "capacity_limit" INTEGER DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_server_group";
CREATE TABLE "v2_server_group" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "name" varchar(255) NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_client_entry_group_ip";
DROP TABLE IF EXISTS "v2_client_entry_group_member";
DROP TABLE IF EXISTS "v2_client_entry_group";
CREATE TABLE "v2_client_entry_group" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "code" varchar(64) NOT NULL, "name" varchar(255) NOT NULL, "display_name" varchar(255) NOT NULL, "strategy" varchar(32) NOT NULL, "hide_member_nodes" SMALLINT NOT NULL DEFAULT '0', "show" SMALLINT NOT NULL DEFAULT '1', "remote_enabled" SMALLINT NOT NULL DEFAULT '0', "remote_host" varchar(255) NOT NULL DEFAULT '', "remote_ssh_port" INTEGER NOT NULL DEFAULT '22', "remote_ssh_user" varchar(255) NOT NULL DEFAULT '', "remote_ssh_password" text NOT NULL DEFAULT '', "remote_group_ref" varchar(255) NOT NULL DEFAULT '', "remote_exclude_names" text NOT NULL DEFAULT '[]', "remote_refresh_sec" INTEGER NOT NULL DEFAULT '300', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "uniq_v2_client_entry_group_code" UNIQUE ("code") );
CREATE TABLE "v2_client_entry_group_member" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "entry_group_id" INTEGER NOT NULL, "server_type" varchar(16) NOT NULL, "server_id" INTEGER NOT NULL, "sort" INTEGER DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "uniq_v2_client_entry_group_member" UNIQUE ("entry_group_id", "server_type", "server_id") );
