CREATE TABLE "v2_client_entry_group_ip" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "entry_group_id" INTEGER NOT NULL, "ip" varchar(128) NOT NULL, "sort" INTEGER DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "uniq_v2_client_entry_group_ip" UNIQUE ("entry_group_id", "ip") );
