CREATE TABLE "v2_server_hysteria" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "version" INTEGER NOT NULL, "group_id" varchar(255) NOT NULL, "route_id" varchar(255) DEFAULT NULL, "name" varchar(255) NOT NULL, "parent_id" INTEGER DEFAULT NULL, "host" varchar(255) NOT NULL, "port" varchar(11) NOT NULL, "server_port" INTEGER NOT NULL, "tags" varchar(255) DEFAULT NULL, "rate" varchar(11) NOT NULL, "show" SMALLINT NOT NULL DEFAULT '0', "sort" INTEGER DEFAULT NULL, "up_mbps" INTEGER NOT NULL, "down_mbps" INTEGER NOT NULL, "obfs" varchar(64) DEFAULT NULL, "obfs_password" varchar(255) DEFAULT NULL, "server_name" varchar(64) DEFAULT NULL, "insecure" SMALLINT NOT NULL DEFAULT '0', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
