CREATE TABLE "v2_server_shadowsocks" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "group_id" varchar(255) NOT NULL, "route_id" varchar(255) DEFAULT NULL, "parent_id" INTEGER DEFAULT NULL, "tags" varchar(255) DEFAULT NULL, "name" varchar(255) NOT NULL, "rate" varchar(11) NOT NULL, "host" varchar(255) NOT NULL, "port" varchar(11) NOT NULL, "server_port" INTEGER NOT NULL, "cipher" varchar(255) NOT NULL, "obfs" char(11) DEFAULT NULL, "obfs_settings" varchar(255) DEFAULT NULL, "show" SMALLINT NOT NULL DEFAULT '0', "sort" INTEGER DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
