CREATE TABLE "v2_server_vless" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "group_id" text NOT NULL, "route_id" text, "name" varchar(255) NOT NULL, "parent_id" INTEGER DEFAULT NULL, "host" varchar(255) NOT NULL, "port" INTEGER NOT NULL, "server_port" INTEGER NOT NULL, "tls" SMALLINT NOT NULL, "tls_settings" text, "flow" varchar(64) DEFAULT NULL, "network" varchar(11) NOT NULL, "network_settings" text, "encryption" varchar(64) DEFAULT NULL, "encryption_settings" text, "tags" text, "rate" varchar(11) NOT NULL, "show" SMALLINT NOT NULL DEFAULT '0', "sort" INTEGER DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_server_vmess";
CREATE TABLE "v2_server_vmess" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "group_id" varchar(255) NOT NULL, "route_id" varchar(255) DEFAULT NULL, "name" varchar(255) NOT NULL, "parent_id" INTEGER DEFAULT NULL, "host" varchar(255) NOT NULL, "port" varchar(11) NOT NULL, "server_port" INTEGER NOT NULL, "tls" SMALLINT NOT NULL DEFAULT '0', "tags" varchar(255) DEFAULT NULL, "rate" varchar(11) NOT NULL, "network" varchar(11) NOT NULL, "rules" text, "networkSettings" text, "tlsSettings" text, "ruleSettings" text, "dnsSettings" text, "show" SMALLINT NOT NULL DEFAULT '0', "sort" INTEGER DEFAULT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_server_anytls";
CREATE TABLE "v2_server_anytls" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "group_id" varchar(255) NOT NULL, "route_id" varchar(255) DEFAULT NULL, "name" varchar(255) NOT NULL, "parent_id" INTEGER DEFAULT NULL, "host" varchar(255) NOT NULL, "port" varchar(11) NOT NULL, "server_port" INTEGER NOT NULL, "tags" varchar(255) DEFAULT NULL, "rate" varchar(11) NOT NULL, "show" SMALLINT NOT NULL DEFAULT '0', "sort" INTEGER DEFAULT NULL, "server_name" varchar(64) DEFAULT NULL, "insecure" SMALLINT NOT NULL DEFAULT '0', "padding_scheme" text, "ddns_settings" text, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_server_v2node";
CREATE TABLE "v2_server_v2node" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "group_id" varchar(255) NOT NULL, "route_id" varchar(255) DEFAULT NULL, "name" varchar(255) NOT NULL, "parent_id" INTEGER DEFAULT NULL, "host" varchar(255) NOT NULL, "listen_ip" varchar(255) NOT NULL DEFAULT '0.0.0.0', "send_through" varchar(255) DEFAULT NULL, "port" varchar(11) NOT NULL, "server_port" INTEGER NOT NULL, "tags" varchar(255) DEFAULT NULL, "rate" varchar(11) NOT NULL, "show" SMALLINT NOT NULL DEFAULT '0', "sort" INTEGER DEFAULT NULL, "protocol" varchar(24) NOT NULL, "tls" SMALLINT NOT NULL, "tls_settings" text, "flow" varchar(64) DEFAULT NULL, "network" varchar(11) NOT NULL, "network_settings" text, "encryption" varchar(64) DEFAULT NULL, "encryption_settings" text, "disable_sni" SMALLINT NOT NULL DEFAULT '0', "udp_relay_mode" varchar(64) DEFAULT NULL, "zero_rtt_handshake" SMALLINT NOT NULL DEFAULT '0', "congestion_control" varchar(64) DEFAULT NULL, "cipher" varchar(64) DEFAULT NULL, "up_mbps" INTEGER NOT NULL, "down_mbps" INTEGER NOT NULL, "obfs" varchar(64) DEFAULT NULL, "obfs_password" varchar(255) DEFAULT NULL, "padding_scheme" text, "ddns_settings" text, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_stat";
CREATE TABLE "v2_stat" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "record_at" INTEGER NOT NULL, "record_type" char(1) NOT NULL, "order_count" INTEGER NOT NULL, "order_total" INTEGER NOT NULL, "commission_count" INTEGER NOT NULL, "commission_total" INTEGER NOT NULL, "paid_count" INTEGER NOT NULL, "paid_total" INTEGER NOT NULL, "register_count" INTEGER NOT NULL, "invite_count" INTEGER NOT NULL, "transfer_used_total" varchar(32) NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "record_at" UNIQUE ("record_at") );
DROP TABLE IF EXISTS "v2_stat_server";
CREATE TABLE "v2_stat_server" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "server_id" INTEGER NOT NULL, "server_type" char(11) NOT NULL, "u" BIGINT NOT NULL, "d" BIGINT NOT NULL, "record_type" char(1) NOT NULL, "record_at" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "server_id_server_type_record_at" UNIQUE ("server_id","server_type","record_at") );
