CREATE INDEX "idx_v2_stat_server_server_id" ON "v2_stat_server" ("server_id");
DROP TABLE IF EXISTS "v2_stat_user";
CREATE TABLE "v2_stat_user" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "user_id" INTEGER NOT NULL, "server_rate" decimal(10,2) NOT NULL, "u" BIGINT NOT NULL, "d" BIGINT NOT NULL, "record_type" char(2) NOT NULL, "record_at" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "server_rate_user_id_record_at" UNIQUE ("server_rate","user_id","record_at") );
CREATE INDEX "idx_v2_stat_user_user_id" ON "v2_stat_user" ("user_id");
CREATE INDEX "idx_v2_stat_user_record_at" ON "v2_stat_user" ("record_at");
CREATE INDEX "idx_v2_stat_user_server_rate" ON "v2_stat_user" ("server_rate");
DROP TABLE IF EXISTS "v2_ticket";
CREATE TABLE "v2_ticket" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "user_id" INTEGER NOT NULL, "subject" varchar(255) NOT NULL, "level" SMALLINT NOT NULL, "status" SMALLINT NOT NULL DEFAULT '0', "reply_status" SMALLINT NOT NULL DEFAULT '0', "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_ticket_message";
CREATE TABLE "v2_ticket_message" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "user_id" INTEGER NOT NULL, "ticket_id" INTEGER NOT NULL, "message" text NOT NULL, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id") );
DROP TABLE IF EXISTS "v2_user";
CREATE TABLE "v2_user" ( "id" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL, "invite_user_id" INTEGER DEFAULT NULL, "telegram_id" BIGINT DEFAULT NULL, "email" varchar(64) NOT NULL, "password" varchar(64) NOT NULL, "password_algo" char(10) DEFAULT NULL, "password_salt" char(10) DEFAULT NULL, "balance" INTEGER NOT NULL DEFAULT '0', "discount" INTEGER DEFAULT NULL, "commission_type" SMALLINT NOT NULL DEFAULT '0', "commission_rate" INTEGER DEFAULT NULL, "commission_balance" INTEGER NOT NULL DEFAULT '0', "t" INTEGER NOT NULL DEFAULT '0', "u" BIGINT NOT NULL DEFAULT '0', "d" BIGINT NOT NULL DEFAULT '0', "transfer_enable" BIGINT NOT NULL DEFAULT '0', "device_limit" INTEGER DEFAULT NULL, "banned" SMALLINT NOT NULL DEFAULT '0', "is_admin" SMALLINT NOT NULL DEFAULT '0', "last_login_at" INTEGER DEFAULT NULL, "is_staff" SMALLINT NOT NULL DEFAULT '0', "last_login_ip" INTEGER DEFAULT NULL, "uuid" varchar(36) NOT NULL, "group_id" INTEGER DEFAULT NULL, "plan_id" INTEGER DEFAULT NULL, "speed_limit" INTEGER DEFAULT NULL, "auto_renewal" SMALLINT DEFAULT '0', "remind_expire" SMALLINT DEFAULT '1', "remind_traffic" SMALLINT DEFAULT '1', "token" char(32) NOT NULL, "expired_at" BIGINT DEFAULT '0', "remarks" text, "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "email" UNIQUE ("email"), CONSTRAINT "token" UNIQUE ("token") );
DROP TABLE IF EXISTS "v2_runtime_kv";
CREATE TABLE "v2_runtime_kv" ( "k" varchar(191) NOT NULL, "v" text NOT NULL, "expire_at" BIGINT NOT NULL DEFAULT '0', "created_at" BIGINT NOT NULL, "updated_at" BIGINT NOT NULL, PRIMARY KEY ("k") );
