DROP TABLE IF EXISTS "v2_auth_session";
CREATE TABLE "v2_auth_session" ( "id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL, "user_id" INTEGER NOT NULL, "session_id" varchar(64) NOT NULL, "auth_data" text, "ip" varchar(128), "ua" text, "login_at" BIGINT NOT NULL, "expire_at" BIGINT NOT NULL DEFAULT '0', "created_at" BIGINT NOT NULL, "updated_at" BIGINT NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "uniq_user_session" UNIQUE ("user_id", "session_id") );
CREATE INDEX "idx_v2_auth_session_user_id" ON "v2_auth_session" ("user_id");
